11|
12|    protected $description = 'Prune stale cache entries from expired versioned keys';
13|
14|    /**
15|     * Versioned namespaces maintained by CacheInvalidationService.
16|     * New namespaces (e.g. `zabbix_devices`, issue #698) must be listed here so
17|     * `cache:prune-stale` — and its call-count test — stay in sync.
18|     *
19|     * @var array<int, string>
20|     */
21|    public const NAMESPACES = ['hardware_stats', 'gis', 'maps', 'dashboard', 'hr_stats', 'report_todos', 'report_tickets', 'report_units', 'unit_hierarchy', 'calendar', 'zabbix_devices'];
22|
23|    public function handle(CacheInvalidationServiceInterface $cache): int
24|    {
25|        $this->info('Pruning stale cache entries...');
26|
27|        $namespaces = self::NAMESPACES;
28|        $pruned = 0;
29|
30|        foreach ($namespaces as $namespace) {
31|            $currentVersion = $cache->getVersion($namespace);
32|            $threshold = $currentVersion - 10; // Keep last 10 versions
33|
34|            // Redis-specific pruning using tags would be ideal, but we
35|            // preserve backward compatibility by relying on TTL expiry.
36|            // This command is a hook point for future tag-based cleanup.
37|            $this->line("  [{$namespace}] current version: {$currentVersion}");
